  1→/**
  2→ * claude_ue_client.mjs
  3→ *
  4→ * Node.js client for the Claude Code → UE5.7 Bridge.
  5→ *
  6→ * Usage:
  7→ *   import { UEBridge } from './claude_ue_client.mjs';
  8→ *   const bridge = new UEBridge();
  9→ *   await bridge.ping();
 10→ *   await bridge.setCognitiveTrait('pace', 0.2, 'Quick', 'Get to the point');
 11→ */
 12→
 13→const BRIDGE_URL = 'http://localhost:8765';
 14→
 15→export class UEBridge {
 16→  constructor(url = BRIDGE_URL) {
 17→    this.url = url;
 18→  }
 19→
 20→  /**
 21→   * Send command to UE bridge.
 22→   */
 23→  async send(command) {
 24→    try {
 25→      const response = await fetch(this.url, {
 26→        method: 'POST',
 27→        headers: { 'Content-Type': 'application/json' },
 28→        body: JSON.stringify(command)
 29→      });
 30→
 31→      if (!response.ok) {
 32→        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
 33→      }
 34→
 35→      return await response.json();
 36→    } catch (error) {
 37→      if (error.code === 'ECONNREFUSED') {
 38→        throw new Error('UE Bridge not running. Start it in Unreal Editor.');
 39→      }
 40→      throw error;
 41→    }
 42→  }
 43→
 44→  // === High-Level Commands ===
 45→
 46→  /**
 47→   * Test connection to UE.
 48→   */
 49→  async ping() {
 50→    return this.send({ type: 'ping' });
 51→  }
 52→
 53→  /**
 54→   * Log message in UE console.
 55→   */
 56→  async log(message, level = 'info') {
 57→    return this.send({ type: 'log', message, level });
 58→  }
 59→
 60→  /**
 61→   * Get all actors in current level.
 62→   */
 63→  async getActors() {
 64→    return this.send({ type: 'get_actors' });
 65→  }
 66→
 67→  /**
 68→   * Get USD stage information.
 69→   */
 70→  async getUsdStage() {
 71→    return this.send({ type: 'get_usd_stage' });
 72→  }
 73→
 74→  /**
 75→   * Set attribute on USD prim.
 76→   */
 77→  async setUsdAttribute(prim, attribute, value) {
 78→    return this.send({
 79→      type: 'set_usd_attribute',
 80→      prim,
 81→      attribute,
 82→      value
 83→    });
 84→  }
 85→
 86→  /**
 87→   * Create new USD layer.
 88→   */
 89→  async createUsdLayer(name) {
 90→    return this.send({ type: 'create_usd_layer', name });
 91→  }
 92→
 93→  /**
 94→   * Spawn actor in scene.
 95→   */
 96→  async spawnActor(className, location = [0, 0, 0], rotation = [0, 0, 0]) {
 97→    return this.send({
 98→      type: 'spawn_actor',
 99→      class: className,
100→      location,
101→      rotation
102→    });
103→  }
104→
105→  /**
106→   * Spawn Niagara particle system.
107→   */
108→  async spawnNiagara(systemPath, location = [0, 0, 0]) {
109→    return this.send({
110→      type: 'spawn_niagara',
111→      system: systemPath,
112→      location
113→    });
114→  }
115→
116→  // === The Translators Integration ===
117→
118→  /**
119→   * Set a cognitive trait on the profile.
120→   * This updates the USD layer in real-time as answers come in.
121→   */
122→  async setCognitiveTrait(dimension, value, label, behavior) {
123→    return this.send({
124→      type: 'set_cognitive_trait',
125→      dimension,
126→      value,
127→      label,
128→      behavior
129→    });
130→  }
131→
132→  /**
133→   * Send complete profile to UE.
134→   * Called when all 8 questions are answered.
135→   */
136→  async sendProfile(profile) {
137→    const results = [];
138→
139→    // Send each trait
140→    for (const [dim, trait] of Object.entries(profile.traits)) {
141→      const result = await this.setCognitiveTrait(
142→        dim,
143→        trait.value,
144→        trait.label,
145→        trait.behavior
146→      );
147→      results.push(result);
148→    }
149→
150→    // Log completion
151→    await this.log(`Profile complete: ${profile.anchor}`, 'info');
152→
153→    return {
154→      success: true,
155→      checksum: profile.checksum,
156→      anchor: profile.anchor,
157→      traits_sent: results.length
158→    };
159→  }
160→}
161→
162→// === CLI Usage ===
163→
164→async function main() {
165→  const bridge = new UEBridge();
166→
167→  console.log('Testing UE Bridge connection...');
168→
169→  try {
170→    const ping = await bridge.ping();
171→    console.log('Connected:', ping);
172→
173→    // Test cognitive trait
174→    const trait = await bridge.setCognitiveTrait(
175→      'pace',
176→      0.2,
177→      'Quick',
178→      'Get to the point — you process fast'
179→    );
180→    console.log('Set trait:', trait);
181→
182→  } catch (error) {
183→    console.error('Error:', error.message);
184→    process.exit(1);
185→  }
186→}
187→
188→// Run if executed directly
189→if (process.argv[1] && process.argv[1].endsWith('claude_ue_client.mjs')) {
190→  main();
191→}
