 23→UBridgeComponent::UBridgeComponent()
 24→{
 25→    PrimaryComponentTick.bCanEverTick = true;
 26→
 27→    // Resolve home directory reliably on Windows
 28→    // FPlatformProcess::UserHomeDir() can return Documents folder on some configs
 29→    FString HomePath;
 30→
 31→#if PLATFORM_WINDOWS
 32→    // Use USERPROFILE env var directly (most reliable on Windows)
 33→    FString UserProfile = FPlatformMisc::GetEnvironmentVariable(TEXT("USERPROFILE"));
 34→    if (!UserProfile.IsEmpty())
 35→    {
 36→        HomePath = UserProfile;
 37→    }
 38→    else
 39→    {
 40→        HomePath = FPlatformProcess::UserHomeDir();
 41→    }
 42→#else
 43→    HomePath = FPlatformProcess::UserHomeDir();
 44→#endif
 45→
 46→    // Clean up path separators and trailing slashes
 47→    FPaths::NormalizeDirectoryName(HomePath);
 48→
 49→    BridgePath = FPaths::Combine(HomePath, TEXT(".translators"));
 50→}
