 53→void UBridgeComponent::BeginPlay()
 54→{
 55→    Super::BeginPlay();
 56→
 57→    BridgeLog(TEXT("========================================"));
 58→    BridgeLog(TEXT("TRANSLATORS BRIDGE COMPONENT v2.0.0"));
 59→    BridgeLog(TEXT("USD-native communication with JSON fallback"));
 60→    BridgeLog(FString::Printf(TEXT("Bridge Path: %s"), *BridgePath));
 61→    BridgeLog(FString::Printf(TEXT("Resolved state.json: %s"), *GetBridgeFilePath(TEXT("state.json"))));
 62→    BridgeLog(TEXT("========================================"));
 63→
 64→    // Ensure bridge directory exists
 65→    IPlatformFile& PlatformFile = FPlatformFileManager::Get().GetPlatformFile();
 66→    if (!PlatformFile.DirectoryExists(*BridgePath))
 67→    {
 68→        PlatformFile.CreateDirectory(*BridgePath);
 69→        BridgeLog(FString::Printf(TEXT("Created bridge directory: %s"), *BridgePath));
 70→    }
 71→
 72→    SetupFileWatcher();
 73→
 74→    // Check for existing state files (Claude Code may have started first)
 75→    // Prefer USD over JSON
 76→    FString UsdFilePath = GetBridgeFilePath(TEXT("bridge_state.usda"));
 77→    FString JsonFilePath = GetBridgeFilePath(TEXT("state.json"));
 78→
 79→    if (PlatformFile.FileExists(*UsdFilePath))
 80→    {
 81→        BridgeLog(TEXT("Found existing bridge_state.usda - processing..."));
 82→        ProcessStateFile();
 83→    }
 84→    else if (PlatformFile.FileExists(*JsonFilePath))
 85→    {
 86→        BridgeLog(TEXT("Found existing state.json - processing..."));
 87→        ProcessStateFile();
 88→    }
 89→}
