102→void UBridgeComponent::TickComponent(float DeltaTime, ELevelTick TickType, FActorComponentTickFunction* ThisTickFunction)
103→{
104→    Super::TickComponent(DeltaTime, TickType, ThisTickFunction);
105→
106→    // Polling fallback for non-editor builds
107→    if (bUsePolling)
108→    {
109→        PollTimer += DeltaTime;
110→        if (PollTimer >= PollInterval)
111→        {
112→            PollTimer = 0.0f;
113→
114→            FString StateFilePath = GetBridgeFilePath(TEXT("state.json"));
115→            IPlatformFile& PlatformFile = FPlatformFileManager::Get().GetPlatformFile();
116→
117→            if (PlatformFile.FileExists(*StateFilePath))
118→            {
119→                FDateTime ModTime = PlatformFile.GetTimeStamp(*StateFilePath);
120→                if (ModTime > LastStateFileTime)

120→                if (ModTime > LastStateFileTime)
121→                {
122→                    LastStateFileTime = ModTime;
123→                    bStateChangePending = true;
124→                    TimeSinceLastStateChange = 0.0f;
125→                }
126→            }
127→        }
128→    }
129→
130→    // Debounced state file processing
131→    if (bStateChangePending)
132→    {
133→        TimeSinceLastStateChange += DeltaTime;
134→        if (TimeSinceLastStateChange >= DebounceTime)
135→        {
136→            bStateChangePending = false;
137→            ProcessStateFile();
138→        }
139→    }
140→
141→    // Debounced USD file processing
142→    if (bUsdChangePending)
143→    {
144→        TimeSinceLastUsdChange += DeltaTime;
145→        if (TimeSinceLastUsdChange >= DebounceTime)
146→        {
147→            bUsdChangePending = false;
148→            OnUsdFileChanged();
149→        }
150→    }
151→}
