156→void UBridgeComponent::SetupFileWatcher()
157→{
158→#if WITH_DIRECTORY_WATCHER
159→    FDirectoryWatcherModule& DirWatcherModule =
160→        FModuleManager::LoadModuleChecked<FDirectoryWatcherModule>(TEXT("DirectoryWatcher"));
161→    IDirectoryWatcher* DirWatcher = DirWatcherModule.Get();
162→
163→    if (!DirWatcher)
164→    {
165→        BridgeLog(TEXT("ERROR: Could not get DirectoryWatcher module"));
166→        return;
167→    }
168→
169→    IDirectoryWatcher::FDirectoryChanged Callback =
170→        IDirectoryWatcher::FDirectoryChanged::CreateUObject(
171→            this, &UBridgeComponent::OnDirectoryChanged);
172→
173→    uint32 WatchFlags = 0; // No special flags needed
174→
175→    bool bSuccess = DirWatcher->RegisterDirectoryChangedCallback_Handle(
176→        BridgePath, Callback, WatchHandle, WatchFlags);
177→
178→    if (bSuccess)
179→    {
180→        BridgeLog(FString::Printf(TEXT("File watcher registered for: %s"), *BridgePath));
181→    }
182→    else
183→    {
184→        BridgeLog(TEXT("ERROR: Failed to register file watcher"));
185→    }
186→#else
187→    // Non-editor: Use polling in TickComponent
188→    BridgeLog(TEXT("DirectoryWatcher not available - using file polling"));
189→    bUsePolling = true;
190→#endif
191→}
